mapper.select:
SELECT DISTINCT cp.*


    cp.del_flag = '0'

        AND cp.tenant_id = #{query.tenantId}


        AND cp.platform = #{query.platform}


        AND cp.creator_id = #{query.creatorId}


        AND cp.platform_content_id = #{query.platformContentId}


        AND cp.added_source = #{query.addedSource}


        AND cp.metrics_status = #{query.metricsStatus}


        AND (cp.title LIKE CONCAT('%', #{query.title}, '%')
            OR cp.description LIKE CONCAT('%', #{query.title}, '%'))


ORDER BY cp.publish_time DESC, cp.first_seen_at DESC
